// parseArgs parses args and returns options or error.
func parseArgs(argv []string) (*options, error) {
	opts := defaultOptions()
	flags := buildFlags(opts)

	short := map[rune]*flagSpec{}
	long := map[string]*flagSpec{}
	for _, f := range flags {
		if f.short != 0 {
			short[f.short] = f
		}
		long[f.long] = f
	}

	var positional []string
	i := 0
	for i < len(argv) {
		a := argv[i]
		if a == "--" {
			i++
			positional = append(positional, argv[i:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			var val string
			hasVal := false
			if eq := strings.Index(name, "="); eq >= 0 {
				val = name[eq+1:]
				name = name[:eq]
				hasVal = true
			}
			f, ok := long[name]
			if !ok {
				return opts, &FlagError{msg: fmt.Sprintf("unknown flag `%s'", name)}
			}
			if f.kind == kindBool {
				if hasVal {
					// go-flags doesn't expect a value for bools via =; treat as error?
					// Keep simple: return an error
					return opts, &FlagError{msg: fmt.Sprintf("unknown flag `%s'", name)}
				}
				*f.ptrBool = true
				f.set = true
				if f.long == "help" {
					return opts, nil
				}
				if f.long == "version" {
					return opts, nil
				}
				i++
				continue
			}
			if !hasVal {
				i++
				if i >= len(argv) {
					return opts, &FlagError{msg: fmt.Sprintf("expected argument for flag `%s'", flagLabel(f))}
				}
				val = argv[i]
			}
			if err := assignFlag(f, val); err != nil {
				return opts, err
			}
			f.set = true
			i++
			continue
		}
		if len(a) >= 2 && a[0] == '-' {
			// short flag(s) like -f, or -b 4096, or -vf
			// Handle as a single short flag: go-flags does support clustering
			rest := a[1:]
			for len(rest) > 0 {
				r := rune(rest[0])
				rest = rest[1:]
				f, ok := short[r]
				if !ok {
					return opts, &FlagError{msg: fmt.Sprintf("unknown flag `%c'", r)}
				}
				if f.kind == kindBool {
					*f.ptrBool = true
					f.set = true
					if f.long == "help" {
						return opts, nil
					}
					if f.long == "version" {
						return opts, nil
					}
					continue
				}
				// Non-bool: value is either the remainder of rest or the next arg
				var val string
				if len(rest) > 0 {
					val = rest
					rest = ""
				} else {
					i++
					if i >= len(argv) {
						return opts, &FlagError{msg: fmt.Sprintf("expected argument for flag `%s'", flagLabel(f))}
					}
					val = argv[i]
				}
				if err := assignFlag(f, val); err != nil {
					return opts, err
				}
				f.set = true
			}
			i++
			continue
		}
		positional = append(positional, a)
		i++
	}

	opts.args = positional
	return opts, nil
}

func flagLabel(f *flagSpec) string {
	if f.short != 0 {
		return fmt.Sprintf("-%c, --%s", f.short, f.long)
	}
	return fmt.Sprintf("--%s", f.long)
}

func assignFlag(f *flagSpec, val string) error {
	switch f.kind {
	case kindInt:
		n, err := strconv.ParseInt(val, 10, 64)
		if err != nil {
			return &FlagError{msg: fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", flagLabel(f), err.Error())}
		}
		*f.ptrInt = n
	case kindUInt:
		n, err := strconv.ParseUint(val, 10, 64)
		if err != nil {
			return &FlagError{msg: fmt.Sprintf("invalid argument for flag `%s' (expected uint): %s", flagLabel(f), err.Error())}
		}
		*f.ptrUInt = n
	case kindString:
		if len(f.choices) > 0 {
			valid := false
			for _, c := range f.choices {
				if c == val {
					valid = true
					break
				}
			}
			if !valid {
				return &FlagError{msg: fmt.Sprintf("Invalid value `%s' for option `--%s'. Allowed values are: %s", val, f.long, formatChoices(f.choices))}
			}
		}
		*f.ptrString = val
	case kindStringSlice:
		*f.ptrStrSlice = append(*f.ptrStrSlice, val)
	case kindRaw:
		if err := f.raw(val); err != nil {
			return err
		}
	}
	return nil
}

func formatChoices(choices []string) string {
	if len(choices) == 0 {
		return ""
	}
	if len(choices) == 1 {
		return choices[0]
	}
	// last separated by "or"
	return strings.Join(choices[:len(choices)-1], ", ") + " or " + choices[len(choices)-1]
}

// writeHelp writes go-flags-style help to w.
// Width is the terminal width used for wrapping.
func writeHelp(w io.Writer, width int) {
	opts := defaultOptions()
	flags := buildFlags(opts)

	fmt.Fprintln(w, "Usage:")
	fmt.Fprintln(w, "  executable [options] <url>")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Application Options:")

	// Build left-hand side for each flag
	lefts := make([]string, len(flags))
	for i, f := range flags {
		lefts[i] = flagLeft(f)
	}
	// Determine indent column: longest left + 2 spaces, at least (but go-flags uses up to 40 max, after that wraps)
	maxLeft := 0
	for _, l := range lefts {
		if len(l) > maxLeft {
			maxLeft = len(l)
		}
	}
	// go-flags pads to length of longest + some padding; we observed column 44.
	indent := maxLeft + 4

	for i, f := range flags {
		left := lefts[i]
		right := f.desc
		if f.defval != "" {
			right = right + " (default: " + f.defval + ")"
		}
		writeHelpLine(w, left, right, indent, width)
	}
}

func flagLeft(f *flagSpec) string {
	var b strings.Builder
	if f.short != 0 {
		b.WriteString("  -")
		b.WriteRune(f.short)
		b.WriteString(", --")
	} else {
		b.WriteString("      --")
	}
	b.WriteString(f.long)
	if f.arg != "" {
		b.WriteString("=")
		if strings.HasPrefix(f.arg, "[") {
			b.WriteString(f.arg)
		} else {
			b.WriteString("<")
			b.WriteString(f.arg)
			b.WriteString(">")
		}
	}
	if f.repeat {
		b.WriteString("...")
	}
	return b.String()
}

// writeHelpLine writes a single flag help line with wrapped description.
func writeHelpLine(w io.Writer, left, right string, indent, width int) {
	// Left part padded to indent
	line := left
	if len(line) < indent {
		line += strings.Repeat(" ", indent-len(line))
	} else {
		line += " "
	}
	descStart := len(line)
	remaining := width - descStart
	if remaining < 1 {
		remaining = 1
	}

	wrapped := wrapText(right, remaining)
	for i, wline := range wrapped {
		if i == 0 {
			fmt.Fprintln(w, line+wline)
		} else {
			fmt.Fprintln(w, strings.Repeat(" ", descStart)+wline)
		}
	}
}

// wrapText splits s into lines not exceeding w columns using word boundaries,
// and breaks long words with a "-" hyphen (as observed with narrow widths).
func wrapText(s string, w int) []string {
	if w < 1 {
		w = 1
	}
	words := strings.Fields(s)
	var lines []string
	var cur strings.Builder
	for _, word := range words {
		// Break words longer than w
		for len(word) > w {
			if cur.Len() > 0 {
				lines = append(lines, cur.String())
				cur.Reset()
			}
			// break word with hyphen
			lines = append(lines, word[:w-1]+"-")
			word = word[w-1:]
		}
		if cur.Len() == 0 {
			cur.WriteString(word)
		} else if cur.Len()+1+len(word) <= w {
			cur.WriteByte(' ')
			cur.WriteString(word)
		} else {
			lines = append(lines, cur.String())
			cur.Reset()
			cur.WriteString(word)
		}
	}
	if cur.Len() > 0 {
		lines = append(lines, cur.String())
	}
	if len(lines) == 0 {
		lines = []string{""}
	}
	return lines
}

// writeError writes parse error like go-flags does: just the message, followed by usage? No, empirically just message.
func writeError(msg string) {
	fmt.Fprintln(os.Stderr, msg)
}

// terminalWidth detects terminal width for help, defaulting to 80 if not a tty.
func terminalWidth() int {
	if w, _, err := term.GetSize(int(os.Stdout.Fd())); err == nil && w > 0 {
		return w
	}
	if w, _, err := term.GetSize(int(os.Stderr.Fd())); err == nil && w > 0 {
		return w
	}
	return 80
}

// used to ensure strings.* imports are not removed when refactoring
var _ = sort.Strings
EOF
