	"strings"
)

type statusCodeRange struct {
	lo, hi int
}

func parseAcceptedStatusCodes(s string) ([]statusCodeRange, error) {
	if s == "" {
		return nil, fmt.Errorf("invalid status code range: %s", s)
	}
	parts := strings.Split(s, ",")
	var out []statusCodeRange
	for _, p := range parts {
		if strings.Contains(p, "..") {
			sp := strings.Split(p, "..")
			if len(sp) != 2 || sp[0] == "" || sp[1] == "" {
				return nil, fmt.Errorf("invalid status code range: %s", p)
			}
			lo, err := strconv.Atoi(sp[0])
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", sp[0])
			}
			hi, err := strconv.Atoi(sp[1])
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", sp[1])
			}
			out = append(out, statusCodeRange{lo, hi})
		} else {
			n, err := strconv.Atoi(p)
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", p)
			}
			out = append(out, statusCodeRange{n, n + 1})
		}
	}
	return out, nil
}

func isAccepted(code int, ranges []statusCodeRange) bool {
	for _, r := range ranges {
		if code >= r.lo && code < r.hi {
			return true
		}
	}
	return false
}
