package main

import (
	"regexp"
	"strings"
)

// extractLinks returns a list of URL references found in the HTML body, and
// a set of element IDs defined in the page (for fragment checking).
// Link sources include: <a href>, <link href>, <script src>, <img src>,
// <iframe src>, <source src>, <track src>.
func extractLinks(html string) (links []string, ids map[string]bool) {
	ids = map[string]bool{}
	// Find all tags
	tagRE := regexp.MustCompile(`(?is)<([a-zA-Z][a-zA-Z0-9]*)\b([^>]*)>`)
	attrRE := regexp.MustCompile(`(?is)([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))`)
	matches := tagRE.FindAllStringSubmatchIndex(html, -1)
	for _, m := range matches {
		tag := strings.ToLower(html[m[2]:m[3]])
		attrsStr := html[m[4]:m[5]]
		attrs := map[string]string{}
		for _, am := range attrRE.FindAllStringSubmatch(attrsStr, -1) {
			name := strings.ToLower(am[1])
			val := am[2]
			if val == "" {
				val = am[3]
			}
			if val == "" {
				val = am[4]
			}
			attrs[name] = val
		}
		if id, ok := attrs["id"]; ok && id != "" {
			ids[id] = true
		}
		if name, ok := attrs["name"]; ok && name != "" {
			ids[name] = true
		}
		var href string
		switch tag {
		case "a", "link":
			href = attrs["href"]
		case "script", "img", "iframe", "source", "track":
			href = attrs["src"]
		}
		if href != "" {
			links = append(links, href)
		}
	}
	return
}
EOF
