cat > /workspace/run.go << 'EOF'
package main

import (
	"crypto/tls"
	"encoding/json"
	"encoding/xml"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

type pageResult struct {
	url   string
	links []linkResult
}

type linkResult struct {
	url    string
	status int // 0 if errored
	err    string
}

func run(opts *options) error {
	// Validate and prepare
	acceptedRanges, err := parseAcceptedStatusCodes(opts.acceptedStatusCodes)
	if err != nil {
		return err
	}

	// Validate headers
	headerPairs := [][2]string{}
	for _, h := range opts.headers {
		idx := strings.Index(h, ":")
		if idx < 0 {
			return fmt.Errorf("invalid header format")
		}
		headerPairs = append(headerPairs, [2]string{strings.TrimSpace(h[:idx]), strings.TrimSpace(h[idx+1:])})
	}

	var excludes []*regexp.Regexp
	for _, p := range opts.excludes {
		r, err := regexp.Compile(p)
		if err != nil {
			return fmt.Errorf("invalid regular expression: %s", p)
		}
		excludes = append(excludes, r)
	}
	var includes []*regexp.Regexp
	for _, p := range opts.includes {
		r, err := regexp.Compile(p)
		if err != nil {
			return fmt.Errorf("invalid regular expression: %s", p)
		}
		includes = append(includes, r)
	}

	rootURL, err := url.Parse(opts.args[0])
	if err != nil {
		return fmt.Errorf("failed to fetch root page: %v", err)
	}
	if rootURL.Scheme == "" {
		rootURL.Scheme = "http"
	}

	// HTTP client
	var dialer net.Dialer
	if opts.dnsResolver != "" {
		dialer.Resolver = &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context2, network, address string) (net.Conn, error) {
				d := net.Dialer{Timeout: time.Duration(opts.timeout) * time.Second}
				return d.Dial("udp", opts.dnsResolver)
			},
		}
	}
	transport := &http.Transport{
		DialContext:         dialer.DialContext,
		MaxIdleConns:        int(opts.maxConnections),
		MaxConnsPerHost:     int(opts.maxConnectionsPerHost),
		MaxIdleConnsPerHost: int(opts.maxConnectionsPerHost),
		TLSClientConfig:     &tls.Config{InsecureSkipVerify: opts.skipTLSVerification},
	}
	if opts.proxy != "" {
		pURL, err := url.Parse(opts.proxy)
		if err != nil {
			return fmt.Errorf("invalid proxy URL: %s", opts.proxy)
		}
		transport.Proxy = http.ProxyURL(pURL)
	}
	client := &http.Client{
		Transport: transport,
		Timeout:   time.Duration(opts.timeout) * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= int(opts.maxRedirections) {
				return fmt.Errorf("too many redirections")
			}
			return nil
		},
	}
	// Semaphore for max connections
	sem := make(chan struct{}, opts.maxConnections)

	// Fetch root
	rootBody, rootStatus, rootURLFinal, rootErr := httpGet(client, rootURL.String(), headerPairs, sem, int(opts.maxResponseBodySize), false)
	if rootErr != nil {
		return fmt.Errorf("failed to fetch root page: %v", rootErr)
	}
	if !isAccepted(rootStatus, acceptedRanges) {
		return fmt.Errorf("failed to fetch root page: %d", rootStatus)
	}

	rootParsed, _ := url.Parse(rootURLFinal)
	_ = rootParsed

	// BFS crawl
	type pageJob struct {
		url string
	}
	// pages keyed by canonical url
	resMu := sync.Mutex{}
	results := []pageResult{}
	visited := map[string]bool{}
	pageBodies := map[string]string{} // url -> body
	pageIDs := map[string]map[string]bool{}

	// Prime with root
	bodyStr := string(rootBody)
	links, ids := extractLinks(bodyStr)
	pageBodies[rootURL.String()] = bodyStr
	pageIDs[rootURL.String()] = ids
	visited[rootURL.String()] = true

	// Function to check if URL should be excluded/included
	shouldSkip := func(u string) bool {
		for _, r := range excludes {
			if r.MatchString(u) {
				return true
			}
		}
		if len(includes) > 0 {
			for _, r := range includes {
				if r.MatchString(u) {
					return false
				}
			}
			return true
		}
		return false
	}

	normalize := func(base *url.URL, href string) (string, string, bool) {
		// returns full URL, fragment, ok
		ref, err := url.Parse(strings.TrimSpace(href))
		if err != nil {
			return "", "", false
		}
		resolved := base.ResolveReference(ref)
		scheme := strings.ToLower(resolved.Scheme)
		if scheme != "http" && scheme != "https" {
			return "", "", false
		}
		fragment := resolved.Fragment
		resolved.Fragment = ""
		return resolved.String(), fragment, true
	}

	// Collect pages to process
	type toProcess struct {
		pageURL string
		body    string
	}
	queue := []toProcess{{rootURL.String(), bodyStr}}

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		curURL, _ := url.Parse(cur.pageURL)
		curLinks, _ := extractLinks(cur.body)
		_ = links
		// Deduplicate links per page preserving order
		seen := map[string]bool{}
		type linkEntry struct {
			full, frag string
		}
		var lentries []linkEntry
		for _, h := range curLinks {
			full, frag, ok := normalize(curURL, h)
			if !ok {
				continue
			}
			if opts.ignoreFragments {
				frag = ""
			}
			key := full
			if frag != "" {
				key = full + "#" + frag
			}
			if seen[key] {
				continue
			}
			seen[key] = true
			lentries = append(lentries, linkEntry{full, frag})
		}

		// Fetch each link concurrently (bounded by sem inside httpGet)
		var wg sync.WaitGroup
		mu := sync.Mutex{}
		linkResults := make([]linkResult, len(lentries))
		for i, le := range lentries {
			i, le := i, le
			displayURL := le.full
			if le.frag != "" {
				displayURL = le.full + "#" + le.frag
			}
			if shouldSkip(displayURL) {
				linkResults[i] = linkResult{url: "", skip: true}
				continue
			}
			wg.Add(1)
			go func() {
				defer wg.Done()
				// Only HEAD/GET external or same-host link
				body, status, finalURL, err := httpGet(client, le.full, headerPairs, sem, int(opts.maxResponseBodySize), true)
				_ = finalURL
				lr := linkResult{url: displayURL}
				if err != nil {
					lr.err = err.Error()
					mu.Lock()
					linkResults[i] = lr
					mu.Unlock()
					return
				}
				if !isAccepted(status, acceptedRanges) {
					lr.err = strconv.Itoa(status)
					mu.Lock()
					linkResults[i] = lr
					mu.Unlock()
					return
				}
				lr.status = status
				// Fragment check (if we have a fragment and same host)
				if le.frag != "" && !opts.ignoreFragments {
					// Need body to check ids
					bodyStr := string(body)
					_, pIDs := extractLinks(bodyStr)
					if !pIDs[le.frag] {
						lr.status = 0
						lr.err = fmt.Sprintf("id #%s not found", le.frag)
					}
				}
				mu.Lock()
				linkResults[i] = lr
				mu.Unlock()

				// Schedule recursion for same-host HTML pages (not one-page-only)
				if opts.onePageOnly {
					return
				}
				linkU, _ := url.Parse(le.full)
				if linkU.Host != rootURL.Host {
					return
				}
				// Only HTML pages (heuristic: status 2xx and body has <)
				if !strings.Contains(string(body), "<") {
					return
				}
				resMu.Lock()
				if !visited[le.full] {
					visited[le.full] = true
					resMu.Unlock()
					queue = append(queue, toProcess{le.full, string(body)})
				} else {
					resMu.Unlock()
				}
			}()
		}
		wg.Wait()
		// Filter out skipped entries
		var finalLinks []linkResult
		for _, lr := range linkResults {
			if lr.skip {
				continue
			}
			finalLinks = append(finalLinks, lr)
		}
		results = append(results, pageResult{url: cur.pageURL, links: finalLinks})
	}

	// Determine output format
	format := opts.format
	if opts.json && opts.format == "text" {
		format = "json"
	}
	if opts.junit && opts.format == "text" {
		format = "junit"
	}
	verbose := opts.verbose || opts.verboseJSON

	// Color handling for text output
	color := opts.color
	if color == "auto" {
		if _, ok := ttyWidth(os.Stdout); ok {
			color = "always"
		} else {
			color = "never"
		}
	}

	// Check if any errors
	hasError := false
	for _, p := range results {
		for _, l := range p.links {
			if l.err != "" {
