func writeText(w io.Writer, results []pageResult, verbose bool, color bool) {
	yellow := ""
	green := ""
	red := ""
	reset := ""
	if color {
		yellow = "\x1b[33m"
		green = "\x1b[32m"
		red = "\x1b[31m"
		reset = "\x1b[0m"
	}
	for _, p := range results {
		show := verbose
		if !show {
			for _, l := range p.links {
				if l.err != "" {
					show = true
					break
				}
			}
		}
		if !show {
			continue
		}
		fmt.Fprintf(w, "%s%s%s\n", yellow, p.url, reset)
		// Sort: status first (errors last?), let's sort alphabetically by url
		sorted := make([]linkResult, len(p.links))
		copy(sorted, p.links)
		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].url < sorted[j].url })
		for _, l := range sorted {
			if !verbose && l.err == "" {
				continue
			}
			if l.err != "" {
				fmt.Fprintf(w, "\t%s%s%s\t%s\n", red, l.err, reset, l.url)
			} else {
				fmt.Fprintf(w, "\t%s%d%s\t%s\n", green, l.status, reset, l.url)
			}
		}
	}
}

