package main

import (
	"fmt"
	"io"
	"net/http"
	"strings"
)

// httpGet performs a GET request and returns the body, status, final URL, error.
func httpGet(client *http.Client, urlStr string, headers [][2]string, sem chan struct{}, maxBody int, isLink bool) ([]byte, int, string, error) {
	sem <- struct{}{}
	defer func() { <-sem }()

	req, err := http.NewRequest("GET", urlStr, nil)
	if err != nil {
		return nil, 0, urlStr, err
	}
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; muffet)")
	req.Header.Set("Accept", "*/*")
	for _, h := range headers {
		req.Header.Set(h[0], h[1])
	}
	resp, err := client.Do(req)
	if err != nil {
		msg := err.Error()
		// strip "Get \"url\": " prefix common to Go http errors
		if idx := strings.Index(msg, ": "); idx > 0 && strings.HasPrefix(msg, "Get ") {
			msg = msg[idx+2:]
		}
		msg = simplifyErr(msg)
		return nil, 0, urlStr, fmt.Errorf("%s", msg)
	}
	defer resp.Body.Close()
	lr := io.LimitReader(resp.Body, int64(maxBody))
	body, _ := io.ReadAll(lr)
