package main

import (
	"regexp"
	"strings"
)

type linkRef struct {
	Tag  string
	URL  string
	Attr string // attribute name (href or src)
}

// extractLinks returns link references and IDs found in the HTML body.
func extractLinks(html string) (links []linkRef, ids map[string]bool) {
	ids = map[string]bool{}
	tagRE := regexp.MustCompile(`(?is)<([a-zA-Z][a-zA-Z0-9]*)\b([^>]*)>`)
	attrRE := regexp.MustCompile(`(?is)([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))`)
	matches := tagRE.FindAllStringSubmatchIndex(html, -1)
	for _, m := range matches {
		tag := strings.ToLower(html[m[2]:m[3]])
		attrsStr := html[m[4]:m[5]]
		attrs := map[string]string{}
		for _, am := range attrRE.FindAllStringSubmatch(attrsStr, -1) {
			name := strings.ToLower(am[1])
			val := am[2]
			if val == "" {
				val = am[3]
			}
			if val == "" {
				val = am[4]
			}
			attrs[name] = val
		}
		if id, ok := attrs["id"]; ok && id != "" {
			ids[id] = true
		}
		if name, ok := attrs["name"]; ok && name != "" {
			ids[name] = true
		}
		var href, attrName string
		switch tag {
		case "a", "link":
			href = attrs["href"]
			attrName = "href"
		case "script", "img", "iframe", "source", "track":
			href = attrs["src"]
			attrName = "src"
		}
		if href != "" {
			links = append(links, linkRef{Tag: tag, URL: href, Attr: attrName})
		}
	}
	return
}
EOF
